const rows = $input.first().json.rows || [];

// Find pages ranking 4-15 (optimization opportunities)
const opportunities = rows
  .filter(r => r.position >= 4 && r.position <= 15 && r.impressions > 100)
  .sort((a, b) => b.impressions - a.impressions)
  .slice(0, 20);

// Find high impression / low CTR pages  
const lowCtr = rows
  .filter(r => r.impressions > 500 && r.ctr < 0.03)
  .sort((a, b) => b.impressions - a.impressions)
  .slice(0, 10);

const totalImpressions = rows.reduce((s, r) => s + r.impressions, 0);
const totalClicks = rows.reduce((s, r) => s + r.clicks, 0);

return [{
  json: {
    totalImpressions,
    totalClicks,
    avgCtr: totalClicks / Math.max(totalImpressions, 1),
    opportunities,
    lowCtr,
    summary: `Week: ${totalImpressions} impressions, ${totalClicks} clicks, ${(totalClicks/Math.max(totalImpressions,1)*100).toFixed(2)}% CTR`
  }
}];

